"""Build a public aggregate report from actual immutable experiment artifacts."""
import argparse,json,hashlib
from pathlib import Path
from analyze import analyze
def pct(v):return 'unavailable' if v is None else f'{100*v:.1f}%'
def main(root,out):
 root=Path(root);out=Path(out);out.mkdir(parents=True,exist_ok=True);a=analyze(root);freeze=json.loads((root/'freeze.json').read_text(encoding='utf-8'));benchmark=json.loads((root/'controls-manifest.json').read_text(encoding='utf-8'));historical=json.loads((root/'historical-extractive-results.json').read_text(encoding='utf-8'));ledger=sum(m['costUsd'] for m in a['models'].values());holds=sum(m['unresolvedReservationUsd'] for m in a['models'].values())
 lines=['# Evaluator reliability: partial measured report','','The existing evaluator is useful for triage, but these measurements do not establish reliable automatic certification of briefing quality, nor superiority of Distilled.news over simpler baselines. The run is incomplete because the local disk filled. No production code, deployment, accounting, dashboards or publication behavior changed.','','## Scope and frozen protocol','',f"- Branch: `research/evaluator-reliability`, based on `{freeze['baseRevision']}`.",f"- Protocol frozen at `{freeze['frozenAt']}`, SHA-256 `{freeze['protocolSha256']}`.",f"- Constructed sources: {benchmark['cases']} cases, {benchmark['faults']} injected faults and {benchmark['controls']} correct controls, three languages, seven event groups.",'- Independent references derive from the supplied source assertions and controlled transformations. Tested judges never see expected labels. References are AI-curated, not human gold. Valid paraphrases and a necessary update are negative controls.','- A separate 12-case real-source challenge set was constructed from two retained events, preserving quantities, uncertainty and attribution across three output languages. It has **not been run**. It is not full-window published-output quality.','- The original 104 evaluator tests passed before inference; eight analysis/benchmark-construction checks are separate from those model measurements.','','## Completed model measurements','','These are the actual completed subsets, not the planned 42 cases per model. Missing and failed reviews are not counted as correct outputs. The subsets differ and must not be used to rank the two judges.','','| Judge | Attempted | Completed | Correct controls | Case TP / FP / FN / TN | Precision | Recall | F1 | p50 / p95 ms |','| --- | ---: | ---: | ---: | --- | ---: | ---: | ---: | --- |']
 for name,m in a['models'].items():
  q=m['anyFaultDetection'];l=m['latencyCompletedMs'];lines.append(f"| {name} | {m['attempted']} | {m['completed']} | {m['knownCorrectControls']} | {q['TP']} / {q['FP']} / {q['FN']} / {q['TN']} | {pct(q['precision'])} | {pct(q['recall'])} | {pct(q['f1'])} | {l['p50']:.0f} / {l['p95']:.0f} |")
 lines+=['','Case detection means any strict adverse category. Target-category detection is different: a wrong date can be detected as factual without being labeled temporal. No completed correct control triggered the deployed alert in either partial subset. This small constructed sample does not establish a production false-positive rate.','','| Category | GPT TP / FP / FN | GPT F1 | Claude TP / FP / FN | Claude F1 |','| --- | --- | ---: | --- | ---: |']
 g=a['models'].get('openai--gpt-4.1',{});c=a['models'].get('anthropic--claude-sonnet-4.5',{})
 for category in ['factual','citation','coverage','relevance','repetition','temporal','language']:
  x,y=g['byCategory'][category],c['byCategory'][category];lines.append(f"| {category} | {x['TP']} / {x['FP']} / {x['FN']} | {pct(x['f1'])} | {y['TP']} / {y['FP']} / {y['FN']} | {pct(y['f1'])} |")
 lines+=['','The prespecified scoring mask evaluates each injected target category as positive and all categories as negative on correct controls. Collateral effects of a mutation are unlabelled, not asserted negative. These are targeted challenge metrics, not a complete deployment category-confusion matrix. Zero positive observations produce unavailable recall/F1, not a perfect score. Full counts, language strata, uncertainty, failures and disagreements are in `aggregate-results.json`.','','## Errors missed, failures and disagreements','','- GPT-4.1 accepted an English statement when French was explicitly requested; its explanation called the English output correct. The result passed validation and raised no alert. Claude correctly flagged the language mismatch.','- Claude recognized the wrong meeting date as a contradicted factual claim and raised an alert, but labeled the temporal dimension correct because the future tense was appropriate. This is a category disagreement, **not an undetected date error**.','- GPT failed validation on all three attempted language versions of the evacuation-omission fault. Claude failed the attempted Arabic version. Their raw coverage rows correctly identified the omitted district, but extra narrative findings mislabeled the omission as factual/relevance despite otherwise supported/relevant item assessments. The unmodified validator rejected these with `UNBOUND_REVIEW_FINDING`. No result was silently repaired or counted as a clean briefing.','- Storage interruption also left unfinished paid stages. Parser/provider/storage failures are preserved; unresolved operations are not resent.','']
 for name,m in a['models'].items():lines.append(f"- {name}: completed target-category recall {pct(m['targetRecallCompleted'])}; failure-adjusted lower/upper bounds among attempted target faults {pct(m['targetRecallFailureAdjustedLower'])} / {pct(m['targetRecallFailureAdjustedUpper'])}. These bounds do not include unattempted cases.")
 lines+=['','There are '+str(len(a['disagreements']))+' preserved structured disagreements among jointly completed cases. Translations and paired mutations are clustered by their shared event; the seven constructed groups do not justify broad statistical superiority claims.','','## Actual historical baseline execution','','Existing all-headlines and keyword implementations executed on three consecutive retained Arabic windows on 1 November. All 615 input article occurrences were supplied without truncation. These are one exposed, overlapping historical track; extraction completeness flags are absent from the export. They are not untouched held-out events.','','| Window end UTC | Input occurrences | All-headlines items | Keyword items |','| --- | ---: | ---: | ---: |']
 for q in historical['qualification']:
  rows=[r for r in historical['extractiveObservations'] if r['caseId']==q['caseId']];lines.append(f"| {q['windowEnd']} | {q['articles']} | {next(r['selected'] for r in rows if r['system']=='all-headlines')} | {next(r['selected'] for r in rows if r['system']=='keyword')} |")
 lines+=['','Those six deterministic executions made zero model calls and incurred zero model cost. Their selection/reading-load observations are **not quality scores**. Single-LLM and V3 generation, blind paired semantic scoring, and untouched event-independent chronological testing have not run. Therefore there is no measured finding that Distilled.news is better than any baseline. The paired runner reuses the existing engine and baseline implementations, but available code is not an executed experiment.','','## Actual cost and interruption','',f'- Confirmed cost across every local ledger, including failed reviews: **${ledger:.6f}**.',f'- Unresolved reservations in interrupted stages: **${holds:.6f}**, preserved separately; they are not settled as zero.',f"- Recorded paid-stage rows: {sum(m['calls'] for m in a['models'].values())}. Full provider response IDs, usage, actual stage latency and immutable requests/responses remain private.",'- Prices were read from OpenRouter before execution. Existing accounting/prompt/validator code was reused; no live financial records were modified.','- The disk filled during execution. Subsequent read-only remote-snapshot retrieval and proposed reproducible-build cleanup could not pass automatic approval because the approval service timed out/disconnected. Those actions were not executed. At least 1 GB of free disk space was requested before resuming paid work.','','## What remains unperformed','','1. Finish the frozen synthetic roster, without resending unknown or terminal operations.','2. Execute the separate frozen real-source challenge set and retain its metrics separately.','3. Complete qualified full-window V3/single-LLM generation and paired blind baseline quality assessment.','4. Qualify genuinely untouched, event-independent chronological windows after protocol freeze. No held-out quality score is reported.','5. Obtain independent human/expert calibration if a claim of factual scientific accuracy is desired. Automated agreement alone does not supply it.','','The direct evidence supports one actionable conclusion: treat the current evaluator as fallible triage, display failed/unassessable evaluations explicitly, and validate schema robustness and requested-language adherence on new independent material before using its scores as product-quality proof.','']
 public={'status':'partial_storage_interrupted','freeze':freeze,'benchmark':benchmark,'analysis':a,'historicalBaselines':{'sourceExportSha256':historical['sourceExportSha256'],'publicExportSha256':historical['publicExportSha256'],'windows':3,'articleOccurrences':615,'observations':historical['extractiveObservations'],'qualityScores':None,'heldOut':False},'unperformed':['remaining controlled cases','real-source challenge inference','V3/single-LLM paired generation and quality scoring','untouched event-independent chronological evaluation']}
 public['frozenExecutionManifest']=json.loads((root/'controls-run/manifest.json').read_text(encoding='utf-8'))
 lines+=['## Validation record','','The eight analysis/construction checks and the offline TypeScript check passed. The latter included the existing generated Worker bindings. No additional inference was run to tune the primary scores after inspecting failures.','']
 (out/'aggregate-results.json').write_text(json.dumps(public,indent=2)+'\n',encoding='utf-8');(out/'PARTIAL_REPORT.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps({'report':str(out/'PARTIAL_REPORT.md'),'confirmedCostUsd':ledger,'unresolvedReservationsUsd':holds,'completed':sum(m['completed'] for m in a['models'].values())}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('root');p.add_argument('out');a=p.parse_args();main(a.root,a.out)
